ck descriptionInline date, time, recurrence, and booking controls in a tabbed panel. Pinned below the event title; not rendered on the front end.'=>'Вметнати контроли за датум, време, повторување и резервации во панел со јазичиња. Закачен под насловот на настанот; не се прикажува на предниот дел.','block keywordbookings'=>'резервации','block keywordcalendar'=>'календар','block keyworddate'=>'датум','block keywordevent'=>'настан','block keywordevents'=>'настани','block keywordlist'=>'листа','block keywordlocations'=>'локации','block keywordplaces'=>'места','block keywordrecurrence'=>'повторување','block keywordschedule'=>'распоред','block keywordtickets'=>'билети','block keywordtime'=>'време','block keywordupcoming'=>'претстојни','block keywordvenues'=>'места на одржување','block keywordwhen'=>'кога','block titleEvent Details'=>'Детали за настанот','block titleEvent Locations'=>'Локации на настани','block titleEvents Calendar'=>'Календар на настани','block titleEvents List'=>'Листа на настани','bookingsNo emails to send for this booking.'=>'Нема е-пошта за испраќање за оваа резервација.','cpt type and view type%1$s %2$s Formats'=>'Формати: %1$s %2$s','eventsFuture <span class="count">(%s)</span>'=>'Идни <span class="count">(%s)</span>' . "\0" . 'Идни <span class="count">(%s)</span>','hex formatColors must be in a valid %s format, such as #FF00EE.'=>'Боите мора да бидат во валиден формат %s, на пример #FF00EE.','spaces per bookingAt least'=>'Најмалку','spaces per bookingAt most'=>'Најмногу','timeat'=>'во','value inherited from another parent item(inherited)'=>'(наследено)']];